// check:visual — visual regression for the site's pages. Screenshot every page at 375/768/1440, light and
// dark, and compare against the last master baseline (pixelmatch). Deterministic because the baseline and
// the candidate are both rendered on the same ubuntu-latest runner (same OS, same self-hosted fonts, same
// chromium), with animations disabled and external requests blocked.
//
// The baseline PNGs live on the `visual-baseline` branch (generated by the visual-baseline workflow on
// master push); master itself carries no binaries. The PR leg checks out that branch and compares.
//
// Modes:
//   pnpm check:visual --generate <outDir>      screenshot every page, write PNGs to <outDir>
//   pnpm check:visual --compare <baselineDir>  screenshot every page, pixelmatch vs <baselineDir>, fail on diff
//
// A missing/empty baseline dir is a first run: it reports "no baseline yet" and passes (bootstrap).
import {
	existsSync,
	mkdirSync,
	readdirSync,
	readFileSync,
	statSync,
	writeFileSync,
} from "node:fs";
import { createServer } from "node:http";
import { homedir } from "node:os";
import path from "node:path";
import pixelmatch from "pixelmatch";
import { chromium } from "playwright-core";
import { PNG } from "pngjs";
import { standalonePages } from "./lib/standalone-pages.mjs";

const DIST = path.resolve(process.env.VISUAL_DIST ?? "dist");
const VIEWPORTS = [
	{ width: 375, height: 800 },
	{ width: 768, height: 1024 },
	{ width: 1440, height: 900 },
];
const THEMES = ["light", "dark"];
// Every page: the standalone pages (the design-system surface), the design-system guide (the component
// showcase), and the main site pages.
const SITE_PAGES = [
	"/",
	"/archive/",
	"/research/",
	"/playground/",
	"/ideas/",
	"/about/",
	"/license/",
	"/posts/ai-boom-trajectories/",
];
const PAGES = [
	...standalonePages().map(
		(rel) =>
			`/${rel
				.replace(/index\.html$/, "")
				.split(path.sep)
				.join("/")}`,
	),
	"/design-system/",
	...SITE_PAGES,
].sort();
// A diff is a failure when more than this fraction of the pixels differ (absorbs sub-pixel AA jitter).
const DIFF_BUDGET = 0.001;
const TYPES = {
	".html": "text/html; charset=utf-8",
	".css": "text/css",
	".js": "text/javascript",
	".json": "application/json",
	".webp": "image/webp",
	".png": "image/png",
	".svg": "image/svg+xml",
	".woff2": "font/woff2",
};

function findChrome() {
	if (process.env.CHROME_PATH) return process.env.CHROME_PATH;
	try {
		const p = chromium.executablePath();
		if (existsSync(p)) return p;
	} catch {}
	const cache = path.join(homedir(), "Library/Caches/ms-playwright");
	if (existsSync(cache))
		for (const d of readdirSync(cache)
			.filter((n) => n.startsWith("chromium_headless_shell"))
			.sort()
			.reverse())
			for (const sub of readdirSync(path.join(cache, d))) {
				const exe = path.join(cache, d, sub, "chrome-headless-shell");
				if (existsSync(exe)) return exe;
			}
	return undefined;
}

const server = createServer((req, res) => {
	let p = decodeURIComponent((req.url ?? "/").split("?")[0]);
	if (p.endsWith("/")) p += "index.html";
	const file = path.join(DIST, path.normalize(p));
	if (!file.startsWith(DIST) || !existsSync(file) || !statSync(file).isFile()) {
		res.statusCode = 404;
		return res.end("not found");
	}
	res.setHeader(
		"Content-Type",
		TYPES[path.extname(file)] ?? "application/octet-stream",
	);
	res.end(readFileSync(file));
});
await new Promise((r) => server.listen(0, "127.0.0.1", r));
const base = `http://127.0.0.1:${server.address().port}`;

// One page at one viewport+theme, settled and deterministic.
async function shot(browser, urlPath, vp, theme) {
	const ctx = await browser.newContext({ viewport: vp });
	const page = await ctx.newPage();
	// Block every external request: nothing network-dependent may vary between baseline and candidate.
	await page.route(/^https?:\/\//, (r) =>
		r.request().url().startsWith(base) ? r.continue() : r.abort(),
	);
	await ctx.addInitScript((t) => {
		try {
			localStorage.setItem("theme", t);
		} catch {}
	}, theme);
	// Kill every CSS animation and transition so a fade-in cannot be caught mid-flight (the screenshot
	// `animations:"disabled"` flag only stops CSS animations, not JS-driven transitions).
	await page.addInitScript(() => {
		const style = document.createElement("style");
		style.textContent = "*,*::before,*::after{animation:none!important;transition:none!important}";
		document.addEventListener("DOMContentLoaded", () => document.head.appendChild(style));
	});
	await page.goto(base + urlPath, { waitUntil: "load" });
	await page.evaluate(
		(t) => document.documentElement.setAttribute("data-theme", t),
		theme,
	);
	await page.waitForTimeout(600); // settle: fonts, layout, the theme script
	const png = await page.screenshot({
		fullPage: false,
		animations: "disabled",
		caret: "hide",
	});
	await ctx.close();
	return png;
}

const name = (urlPath, vp, theme) =>
	`${urlPath.replace(/\//g, "_").replace(/^_/, "") || "index"}__${vp.width}x${vp.height}__${theme}.png`;

const mode = process.argv[2];
const dir = process.argv[3];
if (!mode || !["--generate", "--compare"].includes(mode) || !dir) {
	console.error(
		"Usage: pnpm check:visual --generate <outDir> | --compare <baselineDir>",
	);
	process.exit(2);
}
const outDir = path.resolve(dir);
const browser = await chromium.launch({ executablePath: findChrome() });

// Bootstrap: no baseline yet (the branch is missing or empty) — nothing to compare against. Pass and
// tell the operator to generate the baseline on master.
if (mode === "--compare") {
	const baselineCount = existsSync(outDir)
		? readdirSync(outDir).filter((f) => f.endsWith(".png")).length
		: 0;
	if (!baselineCount) {
		console.log(
			"check:visual: no baseline yet (first run) — the visual-baseline workflow generates it on the next master push.",
		);
		process.exit(0);
	}
}

const shots = [];
for (const urlPath of PAGES)
	for (const vp of VIEWPORTS)
		for (const theme of THEMES)
			shots.push({ urlPath, vp, theme, file: name(urlPath, vp, theme) });

const diffs = [];
let generated = 0;
for (const s of shots) {
	const png = await shot(browser, s.urlPath, s.vp, s.theme);
	if (mode === "--generate") {
		mkdirSync(outDir, { recursive: true });
		writeFileSync(path.join(outDir, s.file), png);
		generated++;
		continue;
	}
	// --compare
	const baseFile = path.join(outDir, s.file);
	if (!existsSync(baseFile)) {
		diffs.push(
			`${s.file}: no baseline (first run — generate the baseline on master)`,
		);
		continue;
	}
	const a = PNG.sync.read(png);
	const b = PNG.sync.read(readFileSync(baseFile));
	if (a.width !== b.width || a.height !== b.height) {
		diffs.push(
			`${s.file}: size ${a.width}x${a.height} vs baseline ${b.width}x${b.height}`,
		);
		continue;
	}
	const diff = pixelmatch(a.data, b.data, null, a.width, a.height, {
		threshold: 0.1,
	});
	if (diff > Math.floor(a.width * a.height * DIFF_BUDGET))
		diffs.push(
			`${s.file}: ${diff} pixel(s) differ (budget ${Math.floor(a.width * a.height * DIFF_BUDGET)})`,
		);
}
await browser.close();
server.close();

if (mode === "--generate") {
	console.log(
		`check:visual: generated ${generated} baseline image(s) -> ${outDir}`,
	);
	process.exit(0);
}
if (diffs.length) {
	console.error(
		`\ncheck:visual FAILED (${diffs.length}/${shots.length}):\n - ${diffs.join("\n - ")}`,
	);
	process.exit(1);
}
console.log(
	`check:visual passed: ${shots.length} image(s) match the baseline.`,
);
